async function api(url,opts={}){const r=await fetch(url,{credentials:'same-origin',...opts,headers:{...(opts.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(opts.headers||{})}});const d=r.headers.get('content-type')?.includes('json')?await r.json():r;if(!r.ok)throw new Error(d.error||'Request failed');return d}
function toast(msg,error=false){const t=$('#toast');t.textContent=msg;t.className='toast show'+(error?' error':'');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.className='toast',3300)}
