function iemjeePage(){return `${header()}<main class="section white" style="min-height:75vh"><div class="section-head"><div class="eyebrow dark">IEMJEE / IEMCET · ADMISSION TESTS</div><h1>Entrance examination information</h1><p>Review the exam structure before applying. Registration is available after student sign-in.</p></div><div class="catalogue-grid"><article class="catalogue-card"><span class="catalogue-level">B.Tech · IEMJEE</span><h3>Physics, Chemistry & Mathematics</h3><ul><li>90 questions (30 per subject)</li><li>360 marks</li><li>2 hours</li><li>Negative marking: 1 mark per incorrect answer</li><li>Online computer-based test; session options subject to official notice</li></ul></article><article class="catalogue-card"><span class="catalogue-level">BBA / BCA · IEMCET</span><h3>English, General Knowledge & Preliminary Mathematics</h3><p>Preparation areas include verbal ability, general awareness and foundational mathematics. Check the current prospectus for question count, marks and duration.</p></article><article class="catalogue-card"><span class="catalogue-level">MBA / MCA / M.Tech</span><h3>Programme-specific entrance routes</h3><p>MBA: CAT-pattern preparation. MCA: WB JECA. M.Tech: GATE. Verify the accepted test and current eligibility for your programme.</p></article></div><div class="panel" style="margin-top:22px"><h3>Apply for an entrance examination</h3><p>Sign in to your Student Portal first. After sign-in, continue to the official examination registration portal to complete the examination application.</p><button class="btn primary" data-action="exam-register">Student Login & Register →</button> <a class="btn secondary" href="https://exam.iem.edu.in/" target="_blank" rel="noopener">Official examination portal ↗</a></div><p class="muted">Exam pattern and availability can change by admission session. Follow the official prospectus for final details.</p></main>${footer()}`}
function portalAccessPage(){return `${header()}<main class="auth-wrap portal-access-wrap"><section class="auth-card portal-access-card"><div class="portal-access-heading"><span class="pill">IEM SECURE PORTAL</span><h2>Welcome to the IEM Portal</h2><p class="muted">Choose the portal you need. Students can create an account, submit an admission application and track its progress. Authorised IEM staff use the separate Admin Portal.</p></div><div class="portal-access-grid"><article class="card portal-access-option"><div class="eyebrow dark">FOR APPLICANTS</div><h3>Student Portal</h3><p class="muted">Apply for admission, continue a saved application, upload documents and check your application status.</p><div class="portal-access-actions"><a class="btn primary" href="#login">Student Login</a><a class="btn gold" href="#register">New Student? Create Account &amp; Apply</a></div></article><article class="card portal-access-option"><div class="eyebrow dark">FOR AUTHORISED PERSONNEL</div><h3>Admin / Staff Portal</h3><p class="muted">Review applications and manage programmes, fees, faculty and portal content.</p><div class="portal-access-actions"><a class="btn secondary" href="#admin-login">Admin / Staff Login</a></div><p class="portal-access-note">Staff accounts require approval and role assignment by the Super Admin. Student registration never grants admin access.</p></article></div><div class="portal-access-footer"><span class="muted">Already signed in? Open your dashboard from the navigation.</span><a href="#home">← Return to IEM public homepage</a></div></section></main>${footer()}`}
function authPage(mode,audience='student'){const student=audience!=='admin';return `${header()}<main class="auth-wrap ${student?'student-auth-wrap':''}"><section class="auth-card ${student?'student-auth-card':''}"><div class="student-auth-aside"><span class="student-auth-mark">IEM</span><div class="eyebrow">${mode==='register'?'START YOUR APPLICATION':'STUDENT ACCESS'}</div><h2>${mode==='register'?'Create your student account':audience==='admin'?'Staff & administrator sign in':'Welcome back'}</h2><p>${mode==='register'?'One account gives you access to your admission application, document uploads and application updates.':'Sign in to continue your application, upload documents or check your admission status.'}</p><div class="student-auth-points"><span>✓ Save your application and continue later</span><span>✓ Upload documents securely</span><span>✓ Track admission updates in one place</span></div></div><div class="student-auth-form"><span class="pill">${student?'IEM STUDENT PORTAL':'IEM ADMINISTRATION'}</span><h3>${mode==='register'?'Applicant details':'Sign in to your account'}</h3><p class="muted">${mode==='register'?'Enter your details to create an account. No email OTP is required.':'Use the email address and password associated with your account.'}</p><form id="auth-form">${mode==='register'?`<div class="field"><label>Full name</label><input name="name" required minlength="2" autocomplete="name" placeholder="Enter your full name"></div>`:''}<div class="field"><label>Email address</label><input name="email" type="email" required autocomplete="${mode==='register'?'email':'username'}" placeholder="you@example.com"></div>${mode==='register'?`<div class="field"><label>Mobile number</label><input name="phone" type="tel" inputmode="numeric" required pattern="[6-9][0-9]{9}" maxlength="10" minlength="10" placeholder="10-digit number starting 6–9" title="Enter exactly 10 digits, starting with 6, 7, 8 or 9." autocomplete="tel"><small class="field-hint">Enter 10 digits beginning with 6, 7, 8 or 9.</small></div>`:''}<div class="field"><label>Password</label><input name="password" type="password" required minlength="${mode==='register'?8:1}" maxlength="72" ${mode==='register'?'pattern="(?=.*[a-z])(?=.*[A-Z])(?=.*[0-9]).{8,72}"':''} title="At least 8 characters, including uppercase, lowercase and a number" autocomplete="${mode==='register'?'new-password':'current-password'}" placeholder="${mode==='register'?'At least 8 characters':'Your password'}"></div>${mode==='register'?`<label class="check"><input type="checkbox" name="terms" required> I agree to the terms of use and privacy notice.</label>`:''}<button class="btn primary student-auth-submit" style="width:100%;margin-top:10px">${mode==='register'?'Create account & continue':'Sign in'}</button></form>${mode==='login'?'<p class="student-auth-switch"><a href="#forgot-password">Forgot password?</a></p>':''}<p class="student-auth-switch">${mode==='register'?'Already have an account?':'New to IEM admissions?'} <a href="#${mode==='register'?'login':'register'}">${mode==='register'?'Sign in':'Create an account'}</a></p>${student?'<a class="student-auth-home" href="#home">← Back to IEM homepage</a>':''}</div></section></main>${footer()}`}

function forgotPasswordPage(){return `${header()}<main class="auth-wrap"><section class="auth-card" style="max-width:520px"><div class="student-auth-form" style="width:100%"><span class="pill">ACCOUNT RECOVERY</span><h2>Forgot your password?</h2><p class="muted">Enter the email address registered with your IEM portal account. We’ll send a one-time reset link if an account exists.</p><form id="forgot-password-form"><div class="field"><label>Email address</label><input name="email" type="email" required autocomplete="email" placeholder="you@example.com"></div><button class="btn primary" style="width:100%">Send reset link</button></form><p class="student-auth-switch"><a href="#login">← Back to Student Login</a> · <a href="#admin-login">Admin Login</a></p></div></section></main>${footer()}`}
function resetPasswordPage(){const token=new URLSearchParams(location.hash.split('?')[1]||'').get('token')||'';return `${header()}<main class="auth-wrap"><section class="auth-card" style="max-width:520px"><div class="student-auth-form" style="width:100%"><span class="pill">SECURE PASSWORD RESET</span><h2>Set a new password</h2><p class="muted">Choose a password with at least 8 characters, including uppercase, lowercase and a number. This reset link can be used only once.</p><form id="reset-password-form"><input type="hidden" name="token" value="${esc(token)}"><div class="field"><label>New password</label><input name="password" type="password" required minlength="8" maxlength="72" pattern="(?=.*[a-z])(?=.*[A-Z])(?=.*[0-9]).{8,72}" autocomplete="new-password" placeholder="Enter your new password"></div><div class="field"><label>Confirm new password</label><input name="confirmPassword" type="password" required minlength="8" maxlength="72" autocomplete="new-password" placeholder="Re-enter your new password"></div><button class="btn primary" style="width:100%">Update password</button></form><p class="student-auth-switch"><a href="#login">Back to login</a></p></div></section></main>${footer()}`}
function coursesPage(){const items=(publicData.programs||[]).filter(p=>p.active!==false);const degrees=[...new Set(items.map(p=>p.degree||'Other'))].sort();const cards=items.map(p=>`<article class="catalogue-card" data-course-degree="${esc(p.degree||'Other')}" data-course-search="${esc(`${p.name} ${p.degree} ${p.department||''}`.toLowerCase())}"><div class="catalogue-card-top"><span class="catalogue-level">${esc(p.degree||'Programme')}</span><span class="catalogue-arrow">↗</span></div><h3>${esc(p.name)}</h3><p class="catalogue-dept">${esc(p.department||'IEM Kolkata')}</p><div class="catalogue-meta"><span>◷ ${esc(p.duration||'Duration as per programme')}</span><span>Entrance: ${esc(p.entrance_exam||'Confirm with admissions')}</span></div><button class="btn secondary small" data-action="apply">Apply / enquire</button></article>`).join('');return `${header()}<main class="catalogue-page"><section class="catalogue-hero"><div class="eyebrow">ACADEMIC PROGRAMMES · IEM KOLKATA</div><h1>Explore your <span>next chapter.</span></h1><p>Discover programmes designed to build knowledge, practical skills and career opportunities. Browse by qualification or search for a specific discipline.</p><div class="catalogue-hero-links"><a class="btn gold" href="#home">Back to home</a><a class="catalogue-official-link" href="https://iem.edu.in/courses/" target="_blank" rel="noopener">IEM official course information ↗</a></div></section><section class="catalogue-content"><div class="catalogue-heading"><div><div class="eyebrow dark">PROGRAMME DIRECTORY</div><h2>Find your programme</h2><p class="muted">${items.length} active listings · Use the filters to narrow your options.</p></div><div class="catalogue-search"><input id="course-search" type="search" placeholder="Search courses or departments…" aria-label="Search courses"></div></div><div class="catalogue-filters"><button class="filter-chip active" data-course-filter="all">All programmes</button>${degrees.map(d=>`<button class="filter-chip" data-course-filter="${esc(d)}">${esc(d)}</button>`).join('')}</div><div class="catalogue-grid" id="catalogue-grid">${cards}</div><div id="course-empty" class="panel" hidden>No programmes match your search. Try another keyword or select a different qualification.</div><div class="catalogue-note"><b>Admission information</b><p>Programme availability, approved nomenclature, eligibility, intake, duration and entrance requirements may vary by admission year. Please verify the current details with IEM before applying.</p><a href="https://iem.edu.in/courses/" target="_blank" rel="noopener">Visit IEM’s official course catalogue ↗</a></div></section></main>${footer()}`}
function shell(title,active,content,role='applicant'){const links=role==='applicant'?[['overview','⌂','Dashboard'],['application','▤','My Application'],['documents','⇧','Documents'],['status','◷','Application Status'],['profile','♙','Profile']]:[['overview','⌂','Dashboard'],['applications','▤','Applications'],['programs','▦','Programs'],['fees','₹','Fees'],['content','✎','Website content'],...(user?.isSuperAdmin?[['users','♙','Users & Roles']]:[]),['reports','▥','Reports'],...(user?.isSuperAdmin?[['audit','◷','Audit Trail']]:[])];return `<div class="app-shell"><aside class="sidebar"><a class="brand" href="#home"><img class="brand-logo institutional-logo" data-fallback="/assets/iem-official.png" src="/assets/iem-official.png" alt="IEM official logo"><span>IEM PORTAL<small>${role==='applicant'?'STUDENT SPACE':'ADMISSIONS CONSOLE'}</small></span></a><button class="side-link" data-action="home"><span class="ico">⌂</span>Local Home Page</button><div class="side-label">Workspace</div>${links.map(([id,ico,label])=>`<button class="side-link ${active===id?'active':''}" data-view="${id}"><span class="ico">${ico}</span>${label}</button>`).join('')}<div class="side-bottom"><button class="side-link" data-action="logout">↪ Sign out</button></div></aside>${role==='applicant'?`<nav class="student-mobile-nav"><button class="${active==='overview'?'active':''}" data-view="overview">⌂<small>Home</small></button><button class="${active==='application'?'active':''}" data-view="application">▤<small>Application</small></button><button class="${active==='documents'?'active':''}" data-view="documents">⇧<small>Documents</small></button><button class="${active==='status'?'active':''}" data-view="status">◷<small>Status</small></button><button data-action="home">◎<small>IEM Home</small></button></nav>`:''}<main class="dash-main"><header class="dash-top"><h2>${title}</h2><span class="user-chip">${esc(user?.name)} · ${role==='applicant'?'STUDENT':user?.isSuperAdmin?'SUPER ADMIN':user?.role?.toUpperCase()}</span></header><div class="dash-content">${content}</div></main></div>`}
function statusPill(s){return `<span class="status ${String(s).toLowerCase().replaceAll(' ','-')}">${esc(s)}</span>`}
function applicationProgress(a,documents=[]){
  const personal=a?.personal||{},academic=a?.academic||{};
  const has=(o,keys)=>keys.every(k=>String(o[k]??'').trim().length>0);
  const personalDone=!!a&&has(personal,['firstName','lastName','dob','phone','address']);
  const academicDone=!!a&&has(academic,['tenthBoard','tenthPercent','twelfthBoard','twelfthPercent']);
  const programmeDone=!!a&&!!a.program_id;
  const requiredDocs=['10th Marksheet','12th Marksheet','Photo'];
  const uploaded=requiredDocs.filter(type=>documents.some(d=>d.doc_type===type)).length;
  const docsPct=Math.round(uploaded/requiredDocs.length*20);
  const submitted=!!a&&a.status!=='Draft'&&!!a.submitted_at;
  const stages=[
    {name:'Personal information',points:personalDone?20:0,done:personalDone,detail:personalDone?'Required personal details saved':'Complete your required personal details'},
    {name:'Academic details',points:academicDone?20:0,done:academicDone,detail:academicDone?'Class 10 and 12 details saved':'Add your Class 10 and 12 details'},
    {name:'Programme selection',points:programmeDone?20:0,done:programmeDone,detail:programmeDone?'A programme has been selected':'Choose your preferred programme'},
    {name:'Documents',points:docsPct,done:uploaded===3,detail:`${uploaded} of 3 required documents uploaded`},
    {name:'Final submission',points:submitted?20:0,done:submitted,detail:submitted?'Application submitted to admissions':'Review and submit your completed application'}
  ];
  return {stages,total:stages.reduce((sum,x)=>sum+x.points,0),uploaded};
}
async function applicantView(view='overview'){const d=await api('/api/applications/mine');const notificationData=await api('/api/notifications');appData=d;const a=d.application;if(view==='application'&&a?.status==='Draft')formStep=Math.max(1,Math.min(4,a.step||1));let body='';if(view==='overview'){const progress=applicationProgress(a,d.documents);const completion=progress.total;const docsCount=d.documents.length;const noticeItems=notificationData.notifications.slice(0,3);const historyItems=d.history.slice(-3).reverse();body=`<section class="student-welcome"><div class="student-welcome-copy"><span class="student-eyebrow">IEM · STUDENT ADMISSION PORTAL</span><h1>Welcome back, ${esc(user.name.split(' ')[0])}.</h1><p>Your admission journey, all in one place. Continue your application, keep documents ready and follow every update from the admissions team.</p><div class="student-welcome-actions"><button class="btn gold" data-view="${a?'application':'application'}">${a?'Continue application':'Start your application'} <span aria-hidden="true">→</span></button><button class="btn student-ghost" data-view="status">Track application</button></div></div><div class="student-welcome-status"><span class="status-label">APPLICATION STATUS</span><strong>${a?esc(a.status):'Not started'}</strong><small>${a?esc(a.application_code):'Your application ID will appear here once you begin.'}</small><div class="welcome-progress"><span style="width:${completion}%"></span></div><small>${completion}% journey completed</small></div></section><div class="student-kpi-grid"><article class="student-kpi"><span class="student-kpi-icon">▤</span><div><small>Application ID</small><strong>${a?esc(a.application_code):'—'}</strong><em>${a?'Your unique reference':'Not generated yet'}</em></div></article><article class="student-kpi"><span class="student-kpi-icon">◷</span><div><small>Current status</small><strong>${a?esc(a.status):'Not started'}</strong><em>Admissions progress</em></div></article><article class="student-kpi"><span class="student-kpi-icon">⇧</span><div><small>Documents uploaded</small><strong>${docsCount}</strong><em>Keep required files ready</em></div></article><article class="student-kpi"><span class="student-kpi-icon">✓</span><div><small>Completion</small><strong>${completion}%</strong><em>${a?'Based on saved application steps':'Begin to track progress'}</em></div></article></div><div class="student-dashboard-grid"><section class="student-panel student-progress-panel"><div class="student-panel-head"><div><span class="student-section-kicker">YOUR JOURNEY</span><h2>Application progress</h2><p>Move through each step at your own pace.</p></div><span class="student-progress-percent">${completion}%</span></div><div class="student-progress-track"><span style="width:${completion}%"></span></div><div class="student-step-list">${progress.stages.map((stage,i)=>`<div class="student-step-item ${stage.done?'is-done':stage.points>0?'is-current':''}"><span class="student-step-number">${stage.done?'✓':i+1}</span><span><b>${stage.name}</b><small>${stage.detail}</small></span><small class="milestone-percent">${stage.points}/20%</small></div>`).join('')}</div><div class="student-progress-footer"><span>${a?'Last saved '+esc(a.updated_at):'Your progress will be saved as you complete the application.'}</span><button class="btn primary small" data-view="application">${a?'Resume application':'Get started'} →</button></div></section><section class="student-panel student-actions-panel"><span class="student-section-kicker">QUICK ACCESS</span><h2>What would you like to do?</h2><button class="student-action-row" data-view="application"><span class="student-action-icon">✎</span><span><b>${a?'Review your application':'Complete your application'}</b><small>Personal details, academics and programme</small></span><span>→</span></button><button class="student-action-row" data-view="documents"><span class="student-action-icon">⇧</span><span><b>Manage documents</b><small>Upload and review required documents</small></span><span>→</span></button><button class="student-action-row" data-view="status"><span class="student-action-icon">◷</span><span><b>Track admission status</b><small>View the latest decision and timeline</small></span><span>→</span></button><button class="student-action-row" data-action="home"><span class="student-action-icon">⌂</span><span><b>Explore IEM website</b><small>Courses, campus, faculty and fees</small></span><span>→</span></button></section></div><div class="student-lower-grid"><section class="student-panel"><div class="student-panel-head"><div><span class="student-section-kicker">ADMISSIONS DESK</span><h2>Recent application activity</h2></div><button class="student-text-link" data-view="status">View timeline →</button></div>${historyItems.map(h=>`<div class="student-activity-row">${statusPill(h.status)}<span>${esc(h.note||'Application status updated')}</span><small>${esc(h.created_at)}</small></div>`).join('')||'<div class="student-empty-note">No application activity yet. Updates will appear here once you start your application.</div>'}</section><section class="student-panel"><div class="student-panel-head"><div><span class="student-section-kicker">STAY INFORMED</span><h2>Latest updates</h2></div></div>${noticeItems.map(n=>`<article class="student-notice-row"><span class="student-notice-dot"></span><div><b>${esc(n.title)}</b><p>${esc(n.message)}</p></div></article>`).join('')||'<div class="student-empty-note">You’re all caught up. Important admission notifications will appear here.</div>'}<div class="student-help-strip"><b>Need assistance?</b><span>Contact the admissions team for application-related support.</span><a href="mailto:admissions@iem.edu.in">admissions@iem.edu.in ↗</a></div></section></div>`;}else if(view==='application'){body=applicationForm(a);}else if(view==='documents'){body=documentsView(a,d.documents);}else if(view==='status'){const progress=applicationProgress(a,d.documents);body=`<div class="dash-heading"><div><h1>Application status</h1><p class="muted">Five milestones, each worth 20% of your application completion.</p></div></div>${a?`<div class="panel"><div class="dash-heading"><div><b>${esc(a.application_code)}</b><p class="muted">${esc(a.program_name||'Programme pending')}</p></div>${statusPill(a.status)}</div><div class="student-panel-head"><h2>Overall completion</h2><strong class="student-progress-percent">${progress.total}%</strong></div><div class="student-progress-track"><span style="width:${progress.total}%"></span></div><div class="student-step-list tracker-stage-list">${progress.stages.map((stage,i)=>`<div class="student-step-item ${stage.done?'is-done':stage.points>0?'is-current':''}"><span class="student-step-number">${stage.done?'✓':i+1}</span><span><b>${stage.name}</b><small>${stage.detail}</small></span><strong class="milestone-percent">${stage.points}/20%</strong></div>`).join('')}</div>${a.admin_note?`<p class="demo-flag">Admissions note: ${esc(a.admin_note)}</p>`:''}<h3>Application activity</h3><div class="timeline">${d.history.map(h=>`<div class="timeline-item"><strong>${esc(h.status)}</strong><small>${esc(h.created_at)} · ${esc(h.note||'Status update')}</small></div>`).join('')||'<p>No timeline updates yet.</p>'}</div></div>`:'<div class="panel empty">No application found. Start an application to see your status timeline.</div>'}`;}else if(view==='profile'){body=`<div class="dash-heading"><div><h1>Personal profile</h1><p class="muted">Your account information.</p></div></div><div class="panel"><div class="field"><label>Full name</label><input value="${esc(user.name)}" disabled></div><div class="field"><label>Email</label><input value="${esc(user.email)}" disabled></div><div class="field"><label>Phone</label><input value="${esc(user.phone)}" disabled></div><p class="muted">Profile changes are handled by admissions in this prototype.</p></div>`;}app.innerHTML=shell(view==='overview'?'Student dashboard':view[0].toUpperCase()+view.slice(1),view,body);}
function applicationForm(a){
  const personal=a?.personal||{},academic=a?.academic||{},guardian=a?.guardian||{};
  const val=(o,k)=>esc(o[k]??'');
  const fields=(items,obj)=>items.map(([k,label,type='text',req=true])=>{const yearField=/Year$/i.test(k);const numericAttrs=type==='number'?(yearField?'min="1980" max="2100" step="1" inputmode="numeric"':'min="0" max="100" step="0.01"'):'';return `<div class="field"><label for="app-${k}">${label}${req?' *':''}</label><input id="app-${k}" name="${k}" type="${type}" value="${val(obj,k)}" ${req?'required':''} ${numericAttrs}></div>`}).join('');
  const programs=(publicData?.programs||[]).filter(p=>Number(p.active)!==0);
  const selectedProgram=String(a?.program_id??'');
  return `<div class="dash-heading"><div><h1>Admission application</h1><p class="muted">Complete your personal details, academic qualifications and preferred programme below. You can save a draft and return later.</p></div>${a?statusPill(a.status):'<span class="pill">NEW APPLICATION</span>'}</div>
  <form id="application-form">
    <section class="panel"><h3>1. Personal information</h3><div class="form-grid">${fields([['firstName','First name'],['lastName','Last name'],['dob','Date of birth','date'],['gender','Gender'],['phone','Mobile number','tel'],['address','Address'],['city','City'],['state','State'],['pincode','PIN code']],personal)}</div></section>
    <section class="panel"><h3>2. Academic qualifications</h3><p class="muted">Enter your Class 10 and Class 12 details. Percentage should be between 0 and 100.</p><div class="form-grid">${fields([['tenthBoard','Class 10 board'],['tenthYear','Class 10 passing year','number'],['tenthPercent','Class 10 percentage','number'],['twelfthBoard','Class 12 board'],['twelfthYear','Class 12 passing year','number'],['twelfthPercent','Class 12 percentage','number']],academic)}<div class="field"><label for="app-entranceExam">Entrance examination (if applicable)</label><select id="app-entranceExam" name="entranceExam"><option value="">Select exam</option>${['IEMJEE','IEM Entrance Exam','WBJEE','JEE Main','CAT','MAT','WBJEMAT','Other'].map(x=>`<option value="${esc(x)}" ${academic.entranceExam===x?'selected':''}>${esc(x)}</option>`).join('')}</select></div><div class="field"><label for="app-entranceScore">Entrance score / rank</label><input id="app-entranceScore" name="entranceScore" value="${val(academic,'entranceScore')}"></div></div></section>
    <section class="panel"><h3>3. Programme selection</h3><div class="field"><label for="app-programId">Preferred programme *</label><select id="app-programId" name="programId" required><option value="">Select the programme you want to enrol in</option>${programs.map(p=>`<option value="${esc(p.id)}" ${selectedProgram===String(p.id)?'selected':''}>${esc(p.degree)} — ${esc(p.name)}</option>`).join('')}</select>${programs.length?`<small class="field-hint">${programs.length} active programmes available. Choose one programme before submitting.</small>`:'<small class="field-hint" style="color:#b33">No active programmes are currently available. Please contact admissions.</small>'}</div></section>
    <section class="panel"><h3>4. Guardian details & declaration</h3><div class="form-grid">${fields([['guardianName','Guardian full name'],['guardianPhone','Guardian phone','tel'],['guardianEmail','Guardian email','email',false],['emergencyContact','Emergency contact','tel']],guardian)}</div><label class="check"><input type="checkbox" name="declaration" ${a?.declaration?'checked':''}> I confirm that the information provided is accurate and understand that final admission is subject to institutional verification.</label></section>
    <div style="display:flex;justify-content:flex-end;gap:10px;flex-wrap:wrap;margin:20px 0"><button type="button" class="btn secondary" data-action="save-draft">Save draft</button><button type="button" class="btn primary" data-action="submit-application">Submit application</button></div>
  </form>`;
}
function documentsView(a,docs){const required=['10th Marksheet','12th Marksheet','Photo','Signature','ID Proof'];return `<div class="dash-heading"><div><h1>Document centre</h1><p class="muted">Upload clear PDF, JPG or PNG files. Maximum file size: 5 MB each.</p></div></div><div class="panel"><h3>Required & supporting documents</h3>${required.map(t=>{const d=docs.find(x=>x.doc_type===t);return `<div class="upload-row"><div><b style="font-size:13px">${t}</b><div class="muted" style="font-size:11px">${d?esc(d.original_name)+' · '+d.verified:'Not uploaded'}</div></div><form class="doc-upload" data-type="${t}"><input type="file" name="document" accept=".pdf,.jpg,.jpeg,.png" required><button class="btn secondary small">${d?'Replace':'Upload'}</button></form></div>`}).join('')}<p class="muted" style="font-size:11px">10th marksheet, 12th marksheet and photo are required for final submission. Graduation marksheet can be uploaded under Other for applicable programmes.</p></div><div class="panel"><h3>Uploaded documents</h3>${docs.length?docs.map(d=>`<p style="font-size:12px">${esc(d.doc_type)} · ${esc(d.original_name)} ${statusPill(d.verified)} <a style="color:var(--blue)" href="/api/documents/${d.id}/download" target="_blank">View file ↗</a></p>`).join(''):'<p class="muted">No documents uploaded yet.</p>'}</div>`}
async function adminPage(view='overview'){adminView=view;if(view==='overview'){const d=await api('/api/admin/overview');const rows=d.recent.map(r=>`<tr><td>${esc(r.application_code)} ${String(r.application_code).startsWith('DEMO-IEM26-')?'<span class="pill demo-record-pill">SYNTHETIC</span>':''}</td><td>${esc(r.name)}</td><td>${esc(r.program_name||'—')}</td><td>${statusPill(r.status)}</td><td><button class="btn secondary small" data-open-app="${r.id}">Review</button></td></tr>`).join('');var body=`<div class="dash-heading"><div><h1>Admissions overview</h1><p class="muted">Live operational view of the portal database.</p></div><span class="pill">${esc(user.role.toUpperCase())} ACCESS</span></div><div class="kpis"><div class="kpi"><span>Total applications</span><strong>${d.total}</strong></div><div class="kpi"><span>Submitted / active</span><strong>${d.submitted}</strong></div><div class="kpi"><span>Under review</span><strong>${d.review}</strong></div><div class="kpi"><span>Approved</span><strong>${d.approved}</strong></div></div><div class="panel"><div class="dash-heading"><h3>Recent applications</h3><button class="btn secondary small" data-view="applications">View all</button></div><div class="table-wrap"><table><thead><tr><th>Application ID</th><th>Applicant</th><th>Programme</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows||'<tr><td colspan="5">No applications yet.</td></tr>'}</tbody></table></div></div>`;}else if(view==='applications'){const d=await api('/api/admin/applications');body=`<div class="dash-heading"><div><h1>Applications</h1><p class="muted">Search, filter and review applicant submissions.</p></div><a class="btn secondary small" href="/api/admin/reports.csv">Export CSV ↓</a></div><div class="panel"><div class="toolbar"><input id="app-search" placeholder="Search name, email or application ID"><select id="status-filter"><option value="">All statuses</option>${['Submitted','Under Review','Documents Required','Verified','Shortlisted','Waitlisted','Approved','Rejected'].map(s=>`<option>${s}</option>`).join('')}</select></div><div id="applications-table">${applicationsTable(d.applications)}</div></div>`;}else if(view==='programs'){const d=await api('/api/admin/programs');body=`<div class="dash-heading"><div><h1>Programme management</h1><p class="muted">Manage the catalogue available to applicants.</p></div><button class="btn primary" data-action="add-program">+ Add programme</button></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>ID</th><th>Degree</th><th>Programme</th><th>Department</th><th>Intake</th><th>Entrance exam</th><th>Visibility</th><th>Action</th></tr></thead><tbody>${d.programs.map(p=>`<tr><td>${esc(p.id)}</td><td>${esc(p.degree)}</td><td>${esc(p.name)}</td><td>${esc(p.department)}</td><td>${p.intake}</td><td>${esc(p.entrance_exam||'—')}</td><td>${p.active?'Active':'Hidden'}</td><td><button class="btn secondary small" data-toggle-program="${esc(p.id)}" data-active="${p.active}">${p.active?'Hide':'Publish'}</button></td></tr>`).join('')}</tbody></table></div></div>`;}else if(view==='fees'){const d=await api('/api/admin/fees');body=`<div class="dash-heading"><div><h1>Fee structure</h1><p class="muted">Set one per-semester tuition amount for each programme family (B.Tech, M.Tech, MBA, BBA/BCA/MCA and Ph.D.) and one common per-semester examination fee for all programmes.</p></div></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Programme</th><th>Component</th><th>Amount (INR)</th><th>Frequency</th><th></th></tr></thead><tbody>${d.fees.map(f=>`<tr><td>${esc(f.program_name)}</td><td>${esc(f.component)}</td><td><input type="number" min="0" step="0.01" id="fee-${esc(f.id)}" value="${esc(f.amount)}" style="width:120px;padding:8px;border:1px solid var(--line);border-radius:7px"></td><td>${esc(f.billing_frequency)}</td><td><button class="btn secondary small" data-save-fee="${esc(f.id)}">Save</button></td></tr>`).join('')}</tbody></table></div><p class="muted">Fee updates are saved to the database. Current seed values are zero placeholders.</p></div>`;}else if(view==='content'){const d=await api('/api/admin/content');const directory=await api('/api/admin/directory');const p=d.content.college_profile||{};const scholarships=d.content.scholarships||{};const placements=d.content.placements||{};const announcements=d.content.announcements||{};body=`<div class="dash-heading"><div><h1>Website content</h1><p class="muted">Manage public-facing information using forms. No JSON editing required.</p></div></div>
<div class="panel"><h3>College profile</h3><p class="muted">Update the main institutional information shown across the website.</p><form id="cms-profile" class="form-grid"><div class="field"><label>College name</label><input name="name" value="${esc(p.name||'')}" required></div><div class="field"><label>Tagline</label><input name="tagline_demo" value="${esc(p.tagline_demo||'')}"></div><div class="field span-2"><label>Overview / About text</label><textarea name="overview" rows="4">${esc(p.overview||'')}</textarea></div><div class="field"><label>Contact email</label><input name="contact_email" value="${esc(p.contact_email||'')}"></div><div class="field"><label>Contact phone</label><input name="contact_phone" value="${esc(p.contact_phone||'')}"></div><div class="field span-2"><label>Logo image path or URL</label><input name="logo_path" value="${esc(p.logo_path||'')}"></div><div class="field span-2"><label>Hero image path or URL</label><input name="hero_image_path" value="${esc(p.hero_image_path||'')}"></div><div class="field span-2"><label>Fees disclaimer</label><textarea name="official_fees_note" rows="2">${esc(p.official_fees_note||'')}</textarea></div><div class="field span-2"><button class="btn primary" type="submit">Save college profile</button></div></form></div>
<div class="panel"><h3>Scholarships & financial aid</h3><form id="cms-scholarships" class="form-grid"><div class="field span-2"><label>Introductory information</label><textarea name="notice" rows="3">${esc(scholarships.notice||'')}</textarea></div><div class="field span-2"><label>Scholarship name</label><input name="itemName" placeholder="e.g. Merit scholarship"></div><div class="field"><label>Eligibility</label><input name="eligibility" placeholder="Eligibility criteria"></div><div class="field"><label>Benefit / amount</label><input name="benefit" placeholder="As per official circular"></div><div class="field span-2"><label>Application details / link</label><input name="details" placeholder="Official details URL or instructions"></div><div class="field span-2"><button class="btn primary">Save scholarship information</button></div></form><div class="muted" style="margin-top:8px">Existing scholarship entries: ${Array.isArray(scholarships.items)?scholarships.items.length:0}. Saving adds a new entry when a name is supplied.</div></div>
<div class="panel"><h3>Placements & career services</h3><form id="cms-placements" class="form-grid"><div class="field span-2"><label>Placement overview</label><textarea name="notice" rows="3">${esc(placements.notice||'')}</textarea></div><div class="field"><label>Academic year / batch</label><input name="year" placeholder="2025 pass-out batch"></div><div class="field"><label>Jobs / offers</label><input name="offers" type="number" min="0" value="${esc(placements.offers??'')}"></div><div class="field"><label>Companies</label><input name="companies" type="number" min="0" value="${esc(placements.companies??'')}"></div><div class="field"><label>Median salary</label><input name="median_salary" value="${esc(placements.median_salary||'')}"></div><div class="field span-2"><label>Official placement report URL</label><input name="report_url" value="${esc(placements.report_url||'')}"></div><div class="field span-2"><button class="btn primary">Save placement information</button></div></form></div>
<div class="panel"><h3>News & announcements</h3><form id="cms-announcements" class="form-grid"><div class="field span-2"><label>General notice / intro</label><textarea name="notice" rows="2">${esc(announcements.notice||'')}</textarea></div><div class="field"><label>Announcement title</label><input name="title" placeholder="Notice title"></div><div class="field"><label>Date</label><input name="date" type="date"></div><div class="field span-2"><label>Announcement details</label><textarea name="description" rows="3"></textarea></div><div class="field span-2"><label>Official link</label><input name="url" placeholder="https://..."></div><div class="field span-2"><button class="btn primary">Save announcement</button></div></form><div class="muted" style="margin-top:8px">Existing announcements: ${Array.isArray(announcements.items)?announcements.items.length:0}</div></div>
<div class="panel"><h3>Faculty directory</h3><p class="muted">Edit individual fields in the cards below. Use official titles and verified details.</p><div id="cms-faculty-list" class="grid grid-2">${directory.faculty.map((f,i)=>`<article class="card cms-directory-card" data-kind="faculty"><input type="hidden" data-field="id" value="${esc(f.id)}"><div class="field"><label>Name</label><input data-field="name" value="${esc(f.name)}"></div><div class="field"><label>Designation</label><input data-field="designation" value="${esc(f.designation)}"></div><div class="field"><label>Department</label><input data-field="department" value="${esc(f.department)}"></div><div class="field"><label>Courses / subjects</label><input data-field="qualifications" value="${esc(f.qualifications)}"></div><div class="field"><label>Research interests</label><input data-field="research_interests" value="${esc(f.research_interests)}"></div><div class="field"><label>Profile image path</label><input data-field="photo" value="${esc(f.photo)}"></div><div class="field"><label>Notes</label><input data-field="data_note" value="${esc(f.data_note)}"></div></article>`).join('')}</div><button class="btn primary" data-action="save-directory-form" data-kind="faculty">Save faculty directory</button></div>
<div class="panel"><h3>Events & fests</h3><p class="muted">Edit event cards and their descriptions. Dates should only be published after confirmation.</p><div id="cms-events-list" class="grid grid-2">${directory.events.map((ev,i)=>`<article class="card cms-directory-card" data-kind="events"><input type="hidden" data-field="id" value="${esc(ev.id)}"><div class="field"><label>Event name</label><input data-field="title" value="${esc(ev.title)}"></div><div class="field"><label>Category</label><input data-field="category" value="${esc(ev.category)}"></div><div class="field"><label>Date</label><input data-field="event_date" value="${esc(ev.event_date)}"></div><div class="field"><label>Description</label><textarea data-field="description" rows="3">${esc(ev.description)}</textarea></div><div class="field"><label>Image path</label><input data-field="image" value="${esc(ev.image)}"></div><div class="field"><label>Notes</label><input data-field="data_note" value="${esc(ev.data_note)}"></div></article>`).join('')}</div><button class="btn primary" data-action="save-directory-form" data-kind="events">Save events & fests</button></div>`;}else if(view==='users'){const d=await api('/api/admin/users');body=`<div class="dash-heading"><div><h1>Users & roles</h1><p class="muted">Only you can grant or revoke Admin and Admissions Officer access. Every other new registration is a Student account.</p></div></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Account</th><th>Action</th></tr></thead><tbody>${d.users.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${u.email.toLowerCase()==='shlokagarwal64@gmail.com'?'<strong>SUPER ADMIN</strong>':`<select data-role-user="${u.id}">${[['applicant','Student'],['officer','Admissions Officer'],['admin','Admin']].map(([r,label])=>`<option value="${r}" ${u.role===r?'selected':''}>${label}</option>`).join('')}</select>`}</td><td>${u.active?'Active':'Disabled'}</td><td>${u.email.toLowerCase()==='shlokagarwal64@gmail.com'?'Protected account':`<button class="btn secondary small" data-user-toggle="${u.id}" data-active="${u.active}">${u.active?'Disable':'Enable'}</button>`}</td></tr>`).join('')}</tbody></table></div></div>`;}else if(view==='reports'){const d=await api('/api/admin/overview');const other=Math.max(0,d.submitted-d.review-d.approved-d.rejected);const vals=[['In review',d.review],['Approved',d.approved],['Rejected',d.rejected],['Other submitted',other]];const max=Math.max(1,...vals.map(x=>x[1]));const total=Math.max(1,d.total);const bars=vals.map(([label,n])=>`<div style="display:grid;grid-template-columns:110px 1fr 42px;align-items:center;gap:12px;margin:14px 0"><span>${label}</span><div style="height:16px;background:#e8eef5;border-radius:20px;overflow:hidden"><div style="height:100%;width:${Math.round(n/max*100)}%;background:linear-gradient(90deg,#245b88,#4b9bd0);border-radius:20px"></div></div><b>${n}</b></div>`).join('');const pct=d.total?Math.round(d.approved/d.total*100):0;const a=d.approved/total*100,r=d.review/total*100,j=d.rejected/total*100;const donut=`conic-gradient(#23865b 0 ${a}%, #d5a441 ${a}% ${a+r}%, #c45a5a ${a+r}% ${a+r+j}%, #8b9aaa ${a+r+j}% 100%)`;body=`<div class="dash-heading"><div><h1>Reports & analytics</h1><p class="muted">Graphical view of live application records in the portal database.</p></div><a class="btn primary" href="/api/admin/reports.csv">Download CSV report ↓</a></div><div class="kpis"><div class="kpi"><span>Total applications</span><strong>${d.total}</strong></div><div class="kpi"><span>Submitted / active</span><strong>${d.submitted}</strong></div><div class="kpi"><span>Under review</span><strong>${d.review}</strong></div><div class="kpi"><span>Approved</span><strong>${d.approved}</strong></div></div><div class="grid grid-2"><div class="panel"><h3>Application pipeline</h3><p class="muted">Number of applications by current status.</p>${bars||'<p>No application records yet.</p>'}</div><div class="panel"><h3>Outcome distribution</h3><div style="display:flex;align-items:center;gap:22px;flex-wrap:wrap;padding:16px 0"><div role="img" aria-label="Application outcome chart" style="width:170px;height:170px;border-radius:50%;background:${donut};position:relative;display:grid;place-items:center"><div style="width:105px;height:105px;border-radius:50%;background:white;display:grid;place-items:center;text-align:center"><strong style="font-size:26px">${d.total}</strong><small>Applications</small></div></div><div><p><span style="color:#23865b">●</span> Approved: <b>${d.approved}</b></p><p><span style="color:#d5a441">●</span> In review: <b>${d.review}</b></p><p><span style="color:#c45a5a">●</span> Rejected: <b>${d.rejected}</b></p><p><span style="color:#8b9aaa">●</span> Other submitted: <b>${other}</b></p></div></div><div class="panel" style="background:#f7fafc"><b>${pct}% approval rate</b><p class="muted">Approved applications divided by all records, including drafts. This is a descriptive operational metric, not an admissions prediction.</p></div></div></div><div class="panel"><h3>Data export</h3><p class="muted">Download application IDs, applicant contact fields, programme and current status. Treat exports as confidential student information.</p><a class="btn secondary" href="/api/admin/reports.csv">Export applications CSV ↓</a></div>`;}else if(view==='audit'){const d=await api('/api/admin/audit');body=`<div class="dash-heading"><div><h1>Audit trail</h1><p class="muted">Recent security and administrative events.</p></div></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Entity</th><th>Details</th></tr></thead><tbody>${d.logs.map(x=>`<tr><td>${esc(x.created_at)}</td><td>${esc(x.actor_name||'System')}</td><td>${esc(x.action)}</td><td>${esc(x.entity)} #${esc(x.entity_id)}</td><td>${esc(x.details)}</td></tr>`).join('')}</tbody></table></div></div>`;}app.innerHTML=shell('Admissions administration',view,body,user.role);}
function applicationsTable(rows){return `<div class="table-wrap"><table><thead><tr><th>Application ID</th><th>Applicant</th><th>Email</th><th>Programme</th><th>Status</th><th>Submitted</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.application_code)} ${String(r.application_code).startsWith('DEMO-IEM26-')?'<span class="pill demo-record-pill">SYNTHETIC</span>':''}</td><td>${esc(r.name)}</td><td>${esc(r.email)}</td><td>${esc(r.program_name||'—')}</td><td>${statusPill(r.status)}</td><td>${esc(r.submitted_at||'—')}</td><td><button class="btn secondary small" data-open-app="${r.id}">Review</button></td></tr>`).join('')||'<tr><td colspan="7">No matching applications.</td></tr>'}</tbody></table></div>`}
async function openAdminApp(id){const d=await api('/api/admin/applications/'+id);const a=d.application;currentAdminApp=id;const modal=document.createElement('div');modal.className='modal-backdrop';modal.id='review-modal';modal.innerHTML=`<section class="modal"><div class="modal-head"><div><span class="pill">APPLICATION REVIEW</span><h2 style="margin:8px 0">${esc(a.application_code)}</h2></div><button class="btn outline small" data-action="close-modal">✕</button></div><p class="muted">${esc(a.name)} · ${esc(a.email)} · ${esc(a.phone||'')}</p><div class="grid grid-2"><div class="card"><h3>Personal details</h3><p>${esc(a.personal.firstName||'')} ${esc(a.personal.lastName||'')}<br>${esc(a.personal.dob||'')} · ${esc(a.personal.gender||'')}<br>${esc(a.personal.address||'')}, ${esc(a.personal.city||'')}</p></div><div class="card"><h3>Academic details</h3><p>10th: ${esc(a.academic.tenthBoard||'')} · ${esc(a.academic.tenthPercent||'')}%<br>12th: ${esc(a.academic.twelfthBoard||'')} · ${esc(a.academic.twelfthPercent||'')}%<br>Programme: ${esc(a.program_name||'—')}</p></div></div><div class="panel"><h3>Documents & verification</h3>${d.documents.map(doc=>`<div class="upload-row"><div><b>${esc(doc.doc_type)}</b><div class="muted">${esc(doc.original_name)} · ${doc.size?Math.round(doc.size/1024)+' KB':''} ${statusPill(doc.verified)}</div><a style="color:var(--blue);font-size:11px" href="/api/documents/${doc.id}/download" target="_blank">Open secure document ↗</a></div><div><select id="verify-${doc.id}">${['Pending','Verified','Rejected','Re-upload Required'].map(s=>`<option ${doc.verified===s?'selected':''}>${s}</option>`).join('')}</select><input id="note-${doc.id}" placeholder="Review note" value="${esc(doc.admin_note||'')}" style="width:130px;padding:8px;border:1px solid var(--line);border-radius:7px;margin:4px"><button class="btn secondary small" data-verify="${doc.id}">Save</button></div></div>`).join('')||'<p class="muted">No documents submitted.</p>'}</div><div class="panel"><h3>Decision & status</h3><div class="form-grid"><div class="field"><label>Application status</label><select id="review-status">${['Under Review','Documents Required','Verified','Shortlisted','Waitlisted','Approved','Rejected'].map(s=>`<option ${a.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="field"><label>Admissions note</label><input id="review-note" value="${esc(a.admin_note||'')}" placeholder="Visible to applicant"></div></div><button class="btn primary" data-action="save-review">Save decision</button></div></section>`;document.body.append(modal);}
function initCampusCarousel(){document.querySelectorAll('img[data-fallback]').forEach(img=>{if(img.dataset.fallbackReady)return;img.dataset.fallbackReady='1';const useFallback=()=>{const local=new URL(img.dataset.fallback,location.href).href;if(img.src!==local){img.src=local;img.classList.add('image-fallback');}};img.addEventListener('error',useFallback,{once:true});if(img.complete&&img.naturalWidth===0)useFallback();});const root=document.getElementById('campus-carousel');if(!root||root.dataset.ready)return;root.dataset.ready='1';const slides=[...root.querySelectorAll('.campus-slide')],dots=[...root.querySelectorAll('[data-slide]')],labels=['IEM · GURUKUL BUILDING, KOLKATA','IEM · ASHRAM BUILDING, KOLKATA','IEM · MANAGEMENT HOUSE, KOLKATA','UEM · JAIPUR CAMPUS','UEM · KOLKATA CAMPUS'];let index=0;const show=n=>{index=(n+slides.length)%slides.length;const cap=document.getElementById('campus-slide-caption');if(cap){cap.classList.add('caption-transitioning');}slides.forEach((el,i)=>el.classList.toggle('active',i===index));dots.forEach((el,i)=>el.classList.toggle('active',i===index));if(cap){cap.textContent=labels[index];requestAnimationFrame(()=>cap.classList.remove('caption-transitioning'));}};dots.forEach(d=>d.addEventListener('click',()=>show(Number(d.dataset.slide))));root._slideTimer=setInterval(()=>show(index+1),5000);}
function render(){if(!publicData)return;const hash=location.hash.slice(1).split('?')[0]||'home';if(user&&user.role!=='applicant'&&['overview','applications','programs','fees','content','users','reports','audit'].includes(hash)){adminPage(hash).catch(e=>toast(e.message,true));return;}if(hash==='forgot-password'){app.innerHTML=forgotPasswordPage();return;}if(hash==='reset-password'){app.innerHTML=resetPasswordPage();return;}if(hash==='portal'){app.innerHTML=portalAccessPage();return;}if(hash==='iemjee'){app.innerHTML=iemjeePage();return;}if(['home','about','programs','courses','faculty','fees','campus','events','placements','news','faq','contact','hostel','faculty-directory','gymkhana'].includes(hash)){if(hash==='faculty-directory'){app.innerHTML=facultyDirectoryPage();return;}if(hash==='courses'){app.innerHTML=coursesPage();return;}if(hash==='gymkhana'){app.innerHTML=gymkhanaPage();return;}app.innerHTML=home();initCampusCarousel();if(hash!=='home')setTimeout(()=>document.getElementById(hash)?.scrollIntoView(),50);return;}if(hash==='login'||hash==='register'||hash==='admin-login'){window.scrollTo(0,0);app.innerHTML=authPage(hash==='register'?'register':'login',hash==='admin-login'?'admin':'student');return;}if(user&&user.role!=='applicant'){adminPage(['applications','programs','fees','content','users','reports','audit'].includes(hash)?hash:'overview').catch(e=>toast(e.message,true));return;}if(!user){location.hash='login';return;}if(user.role==='applicant')applicantView(hash==='application'||hash==='documents'||hash==='status'||hash==='profile'?hash:'overview').catch(e=>toast(e.message,true));else adminPage(['applications','programs','fees','content','users','reports','audit'].includes(hash)?hash:'overview').catch(e=>toast(e.message,true));}
function formObject(form){return Object.fromEntries(new FormData(form).entries())}
async function saveDraft(){const f=$('#application-form');const d=formObject(f);const personal={},academic={},guardian={};const groups={1:['firstName','lastName','dob','gender','phone','address','city','state','pincode'],2:['tenthBoard','tenthYear','tenthPercent','twelfthBoard','twelfthYear','twelfthPercent','entranceExam','entranceScore'],4:['guardianName','guardianPhone','guardianEmail','emergencyContact']};const old=appData?.application;for(const k of groups[1])personal[k]=d[k]??old?.personal?.[k]??'';for(const k of groups[2])academic[k]=d[k]??old?.academic?.[k]??'';for(const k of groups[4])guardian[k]=d[k]??old?.guardian?.[k]??'';if(old){Object.assign(personal,old.personal,personal);Object.assign(academic,old.academic,academic);Object.assign(guardian,old.guardian,guardian);}const programId=d.programId||old?.program_id||null;const result=await api('/api/applications/draft',{method:'PUT',body:JSON.stringify({personal,academic,guardian,programId,step:4})});appData={...(appData||{}),application:{...result.application,personal,academic,guardian,program_id:programId},documents:appData?.documents||[],history:appData?.history||[]};toast('Draft saved successfully.');return result;}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.courseFilter!==undefined){activeCourseFilter=b.dataset.courseFilter;document.querySelectorAll('[data-course-filter]').forEach(x=>x.classList.toggle('active',x.dataset.courseFilter===activeCourseFilter));filterCourses();return;}try{if(b.dataset.action==='home'){location.hash='home';return;}if(b.dataset.action==='menu'){$('#nav')?.classList.toggle('open');return;}if(b.dataset.action==='login'){location.hash=user?.role==='applicant'?'overview':'login';return;}if(b.dataset.action==='admin-login'){location.hash='admin-login';return;}if(b.dataset.action==='apply'){if(user?.role==='applicant'){formStep=1;location.hash='application';}else location.hash='portal';return;}if(b.dataset.action==='exam-register'){if(user?.role==='applicant'){window.location.assign('https://exam.iem.edu.in/');}else{sessionStorage.setItem('iem_exam_after_login','1');location.hash='login';}return;}if(b.dataset.action==='logout'){await api('/api/auth/logout',{method:'POST'});user=null;location.hash='home';render();toast('Signed out.');return;}if(b.dataset.view){location.hash=b.dataset.view;return;}if(b.dataset.action==='next-step'){const f=$('#application-form');if(!f.reportValidity())return;formStep=Math.min(4,formStep+1);await saveDraft();await applicantView('application');return;}if(b.dataset.action==='prev-step'){formStep=Math.max(1,formStep-1);await saveDraft();await applicantView('application');return;}if(b.dataset.action==='save-draft'){await saveDraft();return;}if(b.dataset.action==='submit-application'){const f=$('#application-form');if(!f.reportValidity())return;await saveDraft();const declaration=f.elements.declaration?.checked;if(!declaration){toast('Please accept the declaration.',true);return;}await api('/api/applications/submit',{method:'POST',body:JSON.stringify({declaration:true})});toast('Application submitted successfully.');formStep=1;location.hash='status';return;}if(b.dataset.openApp){await openAdminApp(b.dataset.openApp);return;}if(b.dataset.action==='close-modal'){$('#review-modal')?.remove();return;}if(b.dataset.verify){const id=b.dataset.verify;await api('/api/admin/documents/'+id,{method:'PATCH',body:JSON.stringify({verified:$('#verify-'+id).value,note:$('#note-'+id).value})});toast('Document review saved.');return;}if(b.dataset.action==='save-review'){await api('/api/admin/applications/'+currentAdminApp+'/status',{method:'PATCH',body:JSON.stringify({status:$('#review-status').value,note:$('#review-note').value})});toast('Application decision saved and applicant notified.');$('#review-modal')?.remove();await adminPage('applications');return;}if(b.dataset.saveFee){await api('/api/admin/fees/'+b.dataset.saveFee,{method:'PATCH',body:JSON.stringify({amount:$('#fee-'+b.dataset.saveFee).value})});toast('Fee component updated.');return;}if(b.dataset.action==='save-content'){const key=b.dataset.contentKey,id=key==='college_profile'?'profile-json':key==='scholarships'?'scholarship-json':key==='announcements'?'announcements-json':'placements-json';let value;try{value=JSON.parse($('#'+id).value);}catch{throw Error('Please enter valid JSON before saving.');}await api('/api/admin/content',{method:'PATCH',body:JSON.stringify({key,value})});toast('Website content saved.');return;}if(b.dataset.action==='save-directory-form'){const kind=b.dataset.kind,root=kind==='faculty'?'#cms-faculty-list':'#cms-events-list';const items=[...document.querySelectorAll(root+' .cms-directory-card')].map(card=>Object.fromEntries([...card.querySelectorAll('[data-field]')].map(el=>[el.dataset.field,el.value])));await api('/api/admin/directory/'+kind,{method:'PATCH',body:JSON.stringify({items})});toast(kind==='faculty'?'Faculty directory saved.':'Events directory saved.');return;}if(b.dataset.action==='save-directory'){const kind=b.dataset.kind,id=kind==='faculty'?'faculty-json':'events-json';let items;try{items=JSON.parse($('#'+id).value);if(!Array.isArray(items))throw Error();}catch{throw Error('Please enter a valid JSON array.');}await api('/api/admin/directory/'+kind,{method:'PATCH',body:JSON.stringify({items})});toast('Directory updated.');return;}if(b.dataset.action==='add-program'){showProgramModal();return;}if(b.dataset.toggleProgram){await api('/api/admin/programs/'+b.dataset.toggleProgram,{method:'PATCH',body:JSON.stringify({active:b.dataset.active==='1'?false:true})});toast('Programme visibility updated.');await adminPage('programs');return;}if(b.dataset.userToggle){await api('/api/admin/users/'+b.dataset.userToggle,{method:'PATCH',body:JSON.stringify({active:b.dataset.active==='1'?false:true})});toast('User account updated.');await adminPage('users');return;}}catch(err){toast(err.message,true);}});
document.addEventListener('submit',async e=>{if(e.target.id==='cms-profile'){e.preventDefault();try{const d=formObject(e.target);await api('/api/admin/content',{method:'PATCH',body:JSON.stringify({key:'college_profile',value:d})});toast('College profile saved.');}catch(err){toast(err.message,true);}return;}if(e.target.id==='cms-scholarships'){e.preventDefault();try{const old=(await api('/api/admin/content')).content.scholarships||{};const d=formObject(e.target);const items=Array.isArray(old.items)?old.items.slice():[];if(d.itemName){items.push({name:d.itemName,eligibility:d.eligibility,benefit:d.benefit,details:d.details});}await api('/api/admin/content',{method:'PATCH',body:JSON.stringify({key:'scholarships',value:{notice:d.notice,items}})});toast('Scholarship information saved.');await adminPage('content');}catch(err){toast(err.message,true);}return;}if(e.target.id==='cms-placements'){e.preventDefault();try{const d=formObject(e.target);await api('/api/admin/content',{method:'PATCH',body:JSON.stringify({key:'placements',value:d})});toast('Placement information saved.');}catch(err){toast(err.message,true);}return;}if(e.target.id==='cms-announcements'){e.preventDefault();try{const old=(await api('/api/admin/content')).content.announcements||{};const d=formObject(e.target);const items=Array.isArray(old.items)?old.items.slice():[];if(d.title){items.unshift({title:d.title,date:d.date,description:d.description,url:d.url});}await api('/api/admin/content',{method:'PATCH',body:JSON.stringify({key:'announcements',value:{notice:d.notice,items}})});toast('Announcement saved.');await adminPage('content');}catch(err){toast(err.message,true);}return;}if(e.target.id==='forgot-password-form'){e.preventDefault();try{const d=formObject(e.target);const r=await api('/api/auth/forgot-password',{method:'POST',body:JSON.stringify(d)});toast(r.message||'If the account exists, a reset link will be sent.');e.target.reset();}catch(err){toast(err.message,true);}return;}if(e.target.id==='reset-password-form'){e.preventDefault();const d=formObject(e.target);if(d.password!==d.confirmPassword){toast('The passwords do not match.',true);return;}try{const r=await api('/api/auth/reset-password',{method:'POST',body:JSON.stringify({token:d.token,password:d.password})});toast(r.message||'Password updated.');location.hash='login';render();}catch(err){toast(err.message,true);}return;}if(e.target.id==='auth-form'){e.preventDefault();const d=formObject(e.target);try{if(location.hash==='#register'&&!e.target.elements.terms.checked)throw Error('Please accept the terms.');const adminEntry=location.hash==='#admin-login';let r=await api('/api/auth/'+(location.hash==='#register'?'register':'login'),{method:'POST',body:JSON.stringify({...d,audience:adminEntry?'admin':'student'})});if(adminEntry&&r.user.role==='applicant'){await api('/api/auth/logout',{method:'POST'});throw Error('This is the staff/admin login. Please use Student Login for applicant accounts.');}if(!adminEntry&&r.user.role!=='applicant'){await api('/api/auth/logout',{method:'POST'});throw Error('This is an authorised staff account. Please use Admin / Staff Login.');}user=r.user;toast('Welcome, '+user.name.split(' ')[0]+'!');if(user.role==='applicant'&&sessionStorage.getItem('iem_exam_after_login')==='1'){sessionStorage.removeItem('iem_exam_after_login');location.hash='overview';render();window.location.assign('https://exam.iem.edu.in/');return;}location.hash=(location.hash==='#register'&&user.role==='applicant')?'application':'overview';render();}catch(err){toast(err.message,true);}}if(e.target.id==='contact-form'){e.preventDefault();try{const r=await api('/api/contact',{method:'POST',body:JSON.stringify(formObject(e.target))});toast(r.message);e.target.reset();}catch(err){toast(err.message,true);}}if(e.target.classList.contains('doc-upload')){e.preventDefault();if(!appData?.application){toast('Save your application draft before uploading.',true);location.hash='application';return;}const fd=new FormData(e.target);fd.append('docType',e.target.dataset.type);try{await api('/api/applications/documents',{method:'POST',body:fd});toast('Document uploaded securely.');await applicantView('documents');}catch(err){toast(err.message,true);}}});

document.addEventListener('error',e=>{const img=e.target;if(img?.tagName==='IMG'&&img.dataset.fallback&&!img.dataset.fallbackUsed){img.dataset.fallbackUsed='1';img.src=img.dataset.fallback;img.classList.add('image-fallback');}},true);

document.addEventListener('input',e=>{if(e.target.id==='app-search'||e.target.id==='status-filter')filterApps();});document.addEventListener('change',async e=>{if(e.target.dataset.roleUser){try{await api('/api/admin/users/'+e.target.dataset.roleUser,{method:'PATCH',body:JSON.stringify({role:e.target.value})});toast('User role updated.');}catch(err){toast(err.message,true);}}});
let cachedApps=[];async function filterApps(){const q=$('#app-search')?.value||'',s=$('#status-filter')?.value||'';try{const d=await api('/api/admin/applications?q='+encodeURIComponent(q)+'&status='+encodeURIComponent(s));$('#applications-table').innerHTML=applicationsTable(d.applications);}catch(e){toast(e.message,true);}}
function showProgramModal(){const m=document.createElement('div');m.className='modal-backdrop';m.innerHTML=`<section class="modal"><div class="modal-head"><h2>Add programme</h2><button class="btn outline small" data-action="close-modal">✕</button></div><form id="program-form"><div class="form-grid"><div class="field"><label>Program ID</label><input name="id" placeholder="PRG009" required></div><div class="field"><label>Degree</label><input name="degree" placeholder="B.Tech" required></div><div class="field span-2"><label>Programme name</label><input name="name" required></div><div class="field"><label>Department</label><input name="department"></div><div class="field"><label>Duration</label><input name="duration"></div><div class="field span-2"><label>Eligibility note</label><input name="eligibility"></div><div class="field"><label>Intake</label><input name="intake" type="number"></div><div class="field span-2"><label>Entrance examination</label><input name="entrance_exam" placeholder="IEMJEE / IEM Entrance Exam / CAT / MAT"></div></div><button class="btn primary">Create programme</button></form></section>`;document.body.append(m);}
document.addEventListener('submit',async e=>{if(e.target.id==='program-form'){e.preventDefault();try{await api('/api/admin/programs',{method:'POST',body:JSON.stringify(formObject(e.target))});$('#review-modal')?.remove();document.querySelector('.modal-backdrop')?.remove();toast('Programme created.');await adminPage('programs');}catch(err){toast(err.message,true);}}});
let activeCourseFilter='all';function filterCourses(){const q=(document.getElementById('course-search')?.value||'').trim().toLowerCase();let shown=0;document.querySelectorAll('#catalogue-grid .catalogue-card').forEach(card=>{const matchDegree=activeCourseFilter==='all'||card.dataset.courseDegree===activeCourseFilter;const matchText=!q||card.dataset.courseSearch.includes(q);card.hidden=!(matchDegree&&matchText);if(!card.hidden)shown++;});const empty=document.getElementById('course-empty');if(empty)empty.hidden=shown!==0;}
document.addEventListener('error',e=>{const img=e.target;if(img?.tagName==='IMG'&&img.dataset.fallback&&!img.dataset.fallbackUsed){img.dataset.fallbackUsed='1';img.src=img.dataset.fallback;img.classList.add('image-fallback');}},true);

document.addEventListener('input',e=>{if(e.target.id==='course-search')filterCourses();});window.addEventListener('hashchange',()=>{formStep=1;render();if(['login','register','admin-login','portal','iemjee'].includes(location.hash.slice(1)))window.scrollTo(0,0);});
(async()=>{try{publicData=await api('/api/public');try{user=(await api('/api/auth/me')).user;}catch{}render();}catch(e){app.innerHTML=`<div class="auth-wrap"><div class="auth-card"><h2>Portal could not start</h2><p>${esc(e.message)}</p><p>Run <code>npm install</code> and <code>npm start</code> in the project directory.</p></div></div>`;}})();
